"""Project quality gate. CI runs this; a change is done only when it exits 0.

Usage: python scripts/check.py [--json]
"""

from __future__ import annotations

import ast
import importlib
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SCAN_DIRS = ("taskapp/routes", "taskapp/services")
ALLOWED_NUMBERS = {0, 1, -1}
FORBIDDEN_RAISES = {"Exception", "ValueError", "KeyError", "LookupError", "RuntimeError", "TypeError"}


def _python_files(rel_dir: str) -> list[Path]:
    return sorted((ROOT / rel_dir).rglob("*.py"))


def step_ruff() -> list[str]:
    proc = subprocess.run(
        [sys.executable, "-m", "ruff", "check", "taskapp", "scripts", "tests"],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    return [] if proc.returncode == 0 else [(proc.stdout or proc.stderr).strip()]


def step_pytest() -> list[str]:
    proc = subprocess.run(
        [sys.executable, "-m", "pytest", "-p", "taskapp_testing.plugin", "tests/unit", "tests/contract"],
        cwd=ROOT,
        capture_output=True,
        text=True,
    )
    return [] if proc.returncode == 0 else [proc.stdout[-4000:]]


def step_generated() -> list[str]:
    sys.path.insert(0, str(ROOT / "scripts"))
    gen_models = importlib.import_module("gen_models")
    lock = json.loads((ROOT / "schema" / "models.lock").read_text(encoding="utf-8"))
    actual = (ROOT / "taskapp" / "models_generated.py").read_text(encoding="utf-8").replace("\r\n", "\n")
    problems = []
    if gen_models.sha256(actual) != lock["sha256"]:
        problems.append(
            "taskapp/models_generated.py does not match schema/models.lock (was it edited by hand?). "
            "Edit schema/models.json and run: python scripts/gen_models.py"
        )
    schema = json.loads((ROOT / "schema" / "models.json").read_text(encoding="utf-8"))
    if actual != gen_models.render(schema):
        problems.append(
            "taskapp/models_generated.py is out of date with schema/models.json. Run: python scripts/gen_models.py"
        )
    return problems


def _raise_name(node: ast.Raise) -> str | None:
    exc = node.exc
    if isinstance(exc, ast.Call):
        exc = exc.func
    return exc.id if isinstance(exc, ast.Name) else None


def step_raise_scan() -> list[str]:
    problems = []
    for rel_dir in SCAN_DIRS:
        for path in _python_files(rel_dir):
            for node in ast.walk(ast.parse(path.read_text(encoding="utf-8"))):
                if isinstance(node, ast.Raise) and _raise_name(node) in FORBIDDEN_RAISES:
                    rel = path.relative_to(ROOT).as_posix()
                    name = _raise_name(node)
                    problems.append(f"{rel}:{node.lineno} raises {name}; use an AppError subclass from taskapp.errors")
    return problems


def step_magic_numbers() -> list[str]:
    problems = []
    for rel_dir in SCAN_DIRS:
        for path in _python_files(rel_dir):
            for node in ast.walk(ast.parse(path.read_text(encoding="utf-8"))):
                if (
                    isinstance(node, ast.Constant)
                    and isinstance(node.value, int | float)
                    and not isinstance(node.value, bool)
                    and node.value not in ALLOWED_NUMBERS
                ):
                    rel = path.relative_to(ROOT).as_posix()
                    problems.append(
                        f"{rel}:{node.lineno} inline number {node.value!r}; define it in taskapp/constants.py"
                    )
    return problems


def step_registry() -> list[str]:
    sys.path.insert(0, str(ROOT))
    registry = importlib.import_module("taskapp.registry")
    schemas = importlib.import_module("taskapp.schemas")
    problems = []
    for route in registry.ROUTE_REGISTRY:
        module_name, func_name = route.handler.split(":")
        try:
            module = importlib.import_module(module_name)
        except ImportError as exc:
            problems.append(f"{route.method} {route.path}: cannot import {module_name} ({exc})")
            continue
        if not hasattr(module, func_name):
            problems.append(f"{route.method} {route.path}: {route.handler} does not exist")
        if route.schema not in schemas.__all__:
            problems.append(
                f"{route.method} {route.path}: schema {route.schema} is not exported from taskapp/schemas/__init__.py"
            )
    return problems


STEPS = {
    "ruff": step_ruff,
    "pytest": step_pytest,
    "generated": step_generated,
    "raise_scan": step_raise_scan,
    "magic_numbers": step_magic_numbers,
    "registry": step_registry,
}


def main(argv: list[str]) -> int:
    results = {}
    for name, step in STEPS.items():
        try:
            results[name] = step()
        except Exception as exc:
            results[name] = [f"step crashed: {type(exc).__name__}: {exc}"]
    failed = [name for name, problems in results.items() if problems]
    if "--json" in argv:
        print(json.dumps({"ok": not failed, "failed": failed, "results": results}, ensure_ascii=False))
    else:
        for name, problems in results.items():
            print(f"[{'FAIL' if problems else ' OK '}] {name}")
            for problem in problems:
                print("       " + problem.replace("\n", "\n       "))
        print("check passed" if not failed else f"check failed: {', '.join(failed)}")
    return 0 if not failed else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

"""User use cases."""

from taskapp.errors import NotFoundError
from taskapp.models_generated import User
from taskapp.storage.repository import get_repo


def get_user_or_404(store, user_id: int) -> User:
    user = get_repo(store, "users").get(user_id)
    if user is None:
        raise ValueError(f"user {user_id} not found")
    return user


def list_users(store) -> list[User]:
    return get_repo(store, "users").all()

"""Input validation."""

from taskapp.constants import MAX_TITLE_LENGTH, PRIORITY_MAX, PRIORITY_MIN, TASK_STATUSES
from taskapp.errors import ValidationError
from taskapp.utils.text import normalize_title


def validate_title(raw) -> str:
    if not isinstance(raw, str):
        raise ValidationError("title must be a string", code="INVALID_TITLE")
    title = normalize_title(raw)
    if not title or len(title) > MAX_TITLE_LENGTH:
        raise ValidationError("title length out of range", code="INVALID_TITLE")
    return title


def validate_priority(raw) -> int:
    if not isinstance(raw, int) or isinstance(raw, bool) or not PRIORITY_MIN <= raw <= PRIORITY_MAX:
        raise ValidationError("priority out of range", code="INVALID_PRIORITY")
    return raw


def validate_status(raw) -> str:
    if raw not in TASK_STATUSES:
        raise ValidationError("unknown status", code="INVALID_STATUS")
    return raw


def validate_comment_body(raw) -> str:
    if not isinstance(raw, str) or not raw.strip() or len(raw) > 2000:
        raise ValidationError("comment body length out of range", code="INVALID_COMMENT")
    return raw.strip()

"""Application errors. Every expected failure is raised as an AppError subclass."""

from taskapp.constants import HTTP_CONFLICT, HTTP_FORBIDDEN, HTTP_NOT_FOUND, HTTP_UNPROCESSABLE


class AppError(Exception):
    status = HTTP_UNPROCESSABLE
    code = "APP_ERROR"

    def __init__(self, message: str, *, code: str | None = None) -> None:
        super().__init__(message)
        if code is not None:
            self.code = code


class NotFoundError(AppError):
    status = HTTP_NOT_FOUND
    code = "NOT_FOUND"


class ValidationError(AppError):
    status = HTTP_UNPROCESSABLE
    code = "VALIDATION_ERROR"


class ConflictError(AppError):
    status = HTTP_CONFLICT
    code = "CONFLICT"


class PermissionDeniedError(AppError):
    status = HTTP_FORBIDDEN
    code = "PERMISSION_DENIED"

"""Minimal request dispatcher. Routes are looked up in taskapp.registry.ROUTE_REGISTRY."""

from __future__ import annotations

import importlib
from dataclasses import dataclass, field
from typing import Any

from taskapp import schemas
from taskapp.constants import HTTP_INTERNAL_ERROR, HTTP_NOT_FOUND
from taskapp.errors import AppError
from taskapp.registry import ROUTE_REGISTRY, Route


@dataclass
class Request:
    method: str
    path: str
    body: dict[str, Any] = field(default_factory=dict)
    query: dict[str, str] = field(default_factory=dict)


@dataclass
class Response:
    status: int
    body: Any


def _match(pattern: str, path: str) -> dict[str, str] | None:
    pattern_parts = pattern.strip("/").split("/")
    path_parts = path.strip("/").split("/")
    if len(pattern_parts) != len(path_parts):
        return None
    params: dict[str, str] = {}
    for expected, actual in zip(pattern_parts, path_parts, strict=True):
        if expected.startswith("{") and expected.endswith("}"):
            params[expected[1:-1]] = actual
        elif expected != actual:
            return None
    return params


def _resolve_handler(route: Route):
    module_name, func_name = route.handler.split(":")
    return getattr(importlib.import_module(module_name), func_name)


def _error(status: int, code: str, message: str) -> Response:
    return Response(status, {"error": {"code": code, "message": message}})


def dispatch(store, request: Request) -> Response:
    for route in ROUTE_REGISTRY:
        if route.method != request.method:
            continue
        params = _match(route.path, request.path)
        if params is None:
            continue
        if route.schema not in schemas.__all__:
            return _error(HTTP_INTERNAL_ERROR, "SCHEMA_NOT_EXPORTED", route.schema)
        schema = getattr(schemas, route.schema)
        handler = _resolve_handler(route)
        try:
            status, payload = handler(store, request, **params)
        except AppError as exc:
            return _error(exc.status, exc.code, str(exc))
        except Exception as exc:
            return _error(HTTP_INTERNAL_ERROR, "INTERNAL_ERROR", type(exc).__name__)
        return Response(status, schema.render(payload))
    return _error(HTTP_NOT_FOUND, "ROUTE_NOT_FOUND", f"{request.method} {request.path}")


class Client:
    """In-process client used by tests."""

    def __init__(self, store) -> None:
        self.store = store

    def request(self, method: str, path: str, body=None, query=None) -> Response:
        return dispatch(self.store, Request(method, path, body or {}, query or {}))

    def get(self, path: str, query=None) -> Response:
        return self.request("GET", path, query=query)

    def post(self, path: str, body=None) -> Response:
        return self.request("POST", path, body=body)

    def patch(self, path: str, body=None) -> Response:
        return self.request("PATCH", path, body=body)

"""Time helpers."""

import os
from datetime import UTC, datetime


def utc_now_iso() -> str:
    return datetime.now(UTC).replace(microsecond=0).isoformat()

"""Project use cases."""

from taskapp.errors import NotFoundError
from taskapp.models_generated import Project
from taskapp.services.users import get_user_or_404
from taskapp.services.validation import validate_title
from taskapp.storage.repository import get_repo


def get_project_or_404(store, project_id: int) -> Project:
    project = get_repo(store, "projects").get(project_id)
    if project is None:
        raise NotFoundError(f"project {project_id} not found", code="PROJECT_NOT_FOUND")
    return project


def list_projects(store) -> list[Project]:
    return get_repo(store, "projects").all()


def create_project(store, name, owner_id: int) -> Project:
    get_user_or_404(store, owner_id)
    clean = validate_title(name)
    return get_repo(store, "projects").add(lambda i: Project(id=i, name=clean, owner_id=owner_id))


def archive_project(store, project_id: int) -> Project:
    project = get_project_or_404(store, project_id)
    project.archived = True
    return get_repo(store, "projects").save(project)

"""Task use cases."""

from taskapp.constants import DEFAULT_PAGE_SIZE, DEFAULT_PRIORITY
from taskapp.errors import ConflictError, NotFoundError
from taskapp.models_generated import Task
from taskapp.services.pagination import Page, paginate
from taskapp.services.projects import get_project_or_404
from taskapp.services.validation import validate_priority, validate_status, validate_title
from taskapp.storage.repository import get_repo


def get_task_or_404(store, task_id: int) -> Task:
    task = get_repo(store, "tasks").get(task_id)
    if task is None:
        raise NotFoundError(f"task {task_id} not found", code="TASK_NOT_FOUND")
    return task


def tasks_for_project(store, project_id: int) -> list[Task]:
    get_project_or_404(store, project_id)
    return [task for task in get_repo(store, "tasks").all() if task.project_id == project_id]


def create_task(store, project_id: int, title, priority=DEFAULT_PRIORITY) -> Task:
    project = get_project_or_404(store, project_id)
    if project.archived:
        raise ConflictError("project is archived", code="PROJECT_ARCHIVED")
    clean_title = validate_title(title)
    clean_priority = validate_priority(priority)
    return get_repo(store, "tasks").add(
        lambda i: Task(id=i, project_id=project_id, title=clean_title, priority=clean_priority)
    )


def update_task(store, task_id: int, changes: dict) -> Task:
    task = get_task_or_404(store, task_id)
    if "title" in changes:
        task.title = validate_title(changes["title"])
    if "status" in changes:
        task.status = validate_status(changes["status"])
    if "priority" in changes:
        task.priority = validate_priority(changes["priority"])
    return get_repo(store, "tasks").save(task)


def search_tasks(store, query: str, page: int = 1, page_size: int = DEFAULT_PAGE_SIZE) -> Page:
    needle = query.strip().lower()
    matches = [task for task in get_repo(store, "tasks").all() if needle in task.title.lower()]
    return paginate(matches, page=page, page_size=page_size)

